/* Per-account setup proposal. Page-memory choices only, no auth, OS grant or native preference writes. */
(function(){
'use strict';
const drafts=new Map(),completed=new Map();
const steps=['Layout','Theme','Downloads','Review'];
let activePreview=null,activeLayoutFrame=null,activeLayoutConfig=null;
function sendLayoutPreview(){if(!activeLayoutFrame?.isConnected)return;activeLayoutFrame.contentWindow?.postMessage({type:'relaxe-onboarding-preview-config',family:activeLayoutFrame.dataset.family,account:activeLayoutFrame.dataset.account,...activeLayoutConfig},location.origin)}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==activeLayoutFrame?.contentWindow)return;if(event.data?.type==='relaxe-onboarding-preview-ready'){activeLayoutFrame.dataset.ready='true';const status=document.getElementById('setup-layout-status');if(status)status.textContent=activeLayoutFrame.dataset.family==='vertical'?'Live Vertical swipe sample. Swipe inside it, or use Previous sample / Next sample.':'Live feed sample. Scroll inside it to explore.';sendLayoutPreview()}if(event.data?.type==='relaxe-onboarding-preview-page'){const status=document.getElementById('setup-layout-status');if(status)status.textContent=event.data.moved?'Sample changed.':'Paging is unavailable at this boundary, while zoomed, while loading or while a dialog is open.'}});
function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node}
function name(account){return account==='guest'?'Guest':'u/'+account}
function state(account){if(!drafts.has(account))drafts.set(account,{step:0,layout:'large',theme:'system',folder:'',folderDeferred:false,newSetup:true});return drafts.get(account)}
function group(root,title){const section=el('section','settings-group');section.append(el('h3',null,title));const body=el('div','settings-rows utility-panel');section.append(body);root.append(section);return body}
function button(root,title,action,id){const node=el('button','utility-button',title);node.type='button';if(id){node.id=id;node.dataset.category=id}node.addEventListener('click',action);root.append(node);return node}
function note(root,text){root.append(el('p','field-help',text))}
function select(root,title,value,options,change,id){const wrap=el('div','filter-field'),label=el('label',null,title),input=el('select');input.id=id;label.htmlFor=id;for(const [value,title]of options){const option=el('option',null,title);option.value=value;input.append(option)}input.value=value;input.addEventListener('change',()=>change(input.value));wrap.append(label,input);root.append(wrap);return input}
window.RelaxeOnboarding={render(root,account,navigate,config,onComplete){
 activePreview=null;activeLayoutFrame=null;activeLayoutConfig=config;const draft=state(account),layouts=[['compact','Compact card'],['large','Large card'],['gallery','Gallery'],['vertical','Vertical swipe']],themes=[['system','Follow system'],['light','Light'],['dark','Dark'],['amoled','AMOLED']];
 function refresh(focus){const scroll=document.getElementById('settings-scroll'),offset=scroll?.scrollTop;root.replaceChildren();draw();if(scroll)scroll.scrollTop=offset;root.querySelector('#'+(focus||'setup-step-heading'))?.focus({preventScroll:true})}
 function message(text){root.querySelector('#setup-feedback').textContent=text}
 function next(){draft.step=Math.min(3,draft.step+1);refresh();document.getElementById('settings-scroll').scrollTop=0}
 function folderPicker(){const origin=document.activeElement,dialog=el('dialog','utility-modal');dialog.id='setup-folder-dialog';dialog.setAttribute('aria-labelledby','setup-folder-title');const heading=el('h3',null,'Choose a default download folder');heading.id='setup-folder-title';dialog.append(heading,el('p',null,'For '+name(account)+'. Android’s folder picker grants access to the folder you choose. This study uses an example folder and grants no real access.'));const actions=el('div','dialog-actions');dialog.append(actions);root.append(dialog);const close=()=>{dialog.close();dialog.remove();if(origin?.isConnected)origin.focus({preventScroll:true})};button(actions,'Cancel',close).autofocus=true;button(actions,'Use example folder',()=>{const result=new URLSearchParams(location.search).get('setup-folder');close();if(result==='denied'||result==='invalid'){message('Folder access was not granted. Your previous choice is kept; choose another folder or set this up later.');return}draft.folder='/Downloads/Relaxe · example folder';draft.folderDeferred=false;refresh('setup-choose-folder');message('Default folder chosen for '+name(account)+' in this preview only.');});dialog.addEventListener('cancel',event=>{event.preventDefault();close()});dialog.addEventListener('keydown',event=>{if(event.key==='Escape')event.stopPropagation()});dialog.showModal()}
 function draw(){
  activePreview=null;activeLayoutFrame=null;const intro=el('p','compose-notice','Set up '+name(account));root.append(intro);note(root,'Choose the basics for this account. Other accounts keep their own choices.');
  const progress=el('ol','setup-progress');progress.setAttribute('aria-label','Account setup progress');for(const [index,title]of steps.entries()){const item=el('li',null,title);if(index===draft.step)item.setAttribute('aria-current','step');progress.append(item)}root.append(progress);
  const heading=el('h2',null,steps[draft.step]);heading.id='setup-step-heading';heading.tabIndex=-1;root.append(heading);
  if(completed.has(account))note(root,'This account has completed this preview setup. You can review it again; no native settings were changed.');
  if(draft.step===0){const panel=group(root,'Feed layout');select(panel,'Layout',draft.layout,layouts,value=>{draft.layout=value;refresh('setup-layout')},'setup-layout');
   const sample=el('section','setup-live-layout'),heading=el('h3',null,'Feed sample');sample.append(heading);
   const frame=el('iframe','setup-layout-preview');frame.title=layouts.find(pair=>pair[0]===draft.layout)[1]+' feed sample';frame.dataset.family=draft.layout;frame.dataset.account=account==='guest'?'guest':'signed';frame.setAttribute('aria-describedby','setup-layout-status');
   const params=new URLSearchParams({rev:'148',page:'feed',family:draft.layout,focus:'1','onboarding-preview':'1','preview-account':frame.dataset.account,window:config.width,appearance:config.appearance,palette:config.palette,text:config.text});frame.src='settings.html?'+params;frame.addEventListener('load',sendLayoutPreview);activeLayoutFrame=frame;sample.append(frame);
   const status=el('p','field-help','Loading the selected layout’s sample…');status.id='setup-layout-status';status.setAttribute('role','status');sample.append(status);
   if(draft.layout==='vertical'){const actions=el('div','dialog-actions');for(const [label,delta]of [['Previous sample',-1],['Next sample',1]])button(actions,label,()=>frame.contentWindow?.postMessage({type:'relaxe-onboarding-preview-step',delta},location.origin));sample.append(actions)}
   panel.append(sample);if(draft.newSetup&&draft.layout==='large')note(panel,'Starting layout: Large card · Card 1 · Filled. You can choose any of the four families.');note(panel,'Try the sample before continuing. It uses the same rendered feed and media fixtures as the layout editor.');note(panel,'Further layout customization is available in Settings.');}
  if(draft.step===1){const panel=group(root,'Appearance');select(panel,'Theme',draft.theme,themes,value=>{draft.theme=value;refresh('setup-theme')},'setup-theme');const sample=el('article','time-sample setup-theme-sample');sample.append(el('h3',null,'A quiet trail above the clouds'),el('p',null,'hiking · trailreader'),el('p',null,'A familiar view, using your preferred appearance.'));activePreview=previewConfig=>{if(window.RelaxeStudyTheme){const T=window.RelaxeStudyTheme,settings={foundation:'selected',...previewConfig,appearance:draft.theme==='system'?previewConfig.appearance:draft.theme};for(const [key,value]of Object.entries(T.tokens(T.directions[0],settings)))sample.style.setProperty(key,value);T.setStyleAttributes(sample,T.directions[0],settings);}};activePreview(config);panel.append(sample);note(panel,'Follow system uses the device appearance. This sample is illustrative. Your selected mode will use the existing theme system; custom colors and theme-library editing remain in Settings.');}
  if(draft.step===2){const panel=group(root,'Default download location');panel.append(el('p','setup-folder-value',draft.folder||'No folder selected'));button(panel,'Choose folder',folderPicker,'setup-choose-folder');if(draft.folder)button(panel,'Clear this choice',()=>{draft.folder='';draft.folderDeferred=false;refresh('setup-choose-folder')},'setup-clear-folder');note(panel,'Choose a default for '+name(account)+'. Existing per-media and separate NSFW folder choices are not overwritten by this preview.');note(panel,'If no suitable location is configured, downloading keeps the existing setup prompt. Browsing does not need folder access.');}
  if(draft.step===3){const panel=group(root,'Review '+name(account));const summary=el('dl','setup-summary');for(const [label,value]of [['Layout',layouts.find(pair=>pair[0]===draft.layout)[1]],['Theme',themes.find(pair=>pair[0]===draft.theme)[1]],['Default download folder',draft.folder||'Set up later']])summary.append(el('dt',null,label),el('dd',null,value));panel.append(summary);note(panel,'These are account setup choices. Device security, proxy, Android permissions and the shared theme library keep their existing scopes.');button(panel,'Finish setup',()=>{completed.set(account,{layout:draft.layout,theme:draft.theme,folder:draft.folder,folderDeferred:draft.folderDeferred});message('Setup completed for '+name(account)+' in the page-memory preview only. No login, native preference, layout, theme or folder grant changed.');onComplete?.(account);},'setup-finish');}
  const actions=el('div','dialog-actions setup-actions');if(draft.step>0)button(actions,'Previous',()=>{draft.step--;refresh();document.getElementById('settings-scroll').scrollTop=0},'setup-previous');if(draft.step<3)button(actions,draft.step===2&&!draft.folder?'Set up later':'Continue',()=>{if(draft.step===2&&!draft.folder)draft.folderDeferred=true;next()},'setup-next');root.append(actions);
  const feedback=el('p','field-help');feedback.id='setup-feedback';feedback.setAttribute('role','status');root.append(feedback);
 }
 draw();
},isComplete(account){return completed.has(account)},ensureExisting(account,choices){if(drafts.has(account))return;drafts.set(account,{step:0,layout:choices.layout,theme:choices.theme,folder:choices.folder||'',folderDeferred:!choices.folder});completed.set(account,{...choices})},updatePreview(config){activeLayoutConfig=config;activePreview?.(config);sendLayoutPreview()}};
})();
